ee:message.ee:set-payload:
%dw 2.0
output application/json
---
{
  "status": 500,
  "code": "INTERNAL_SERVER_ERROR",
  "message": {
    "message": "Error trying to retrieve client information by mayoristaId"
  },
  "messageServer": "",
  "cause": [
    {
      "origin": app.name,
      "message": "org.mule.extension.http.api.request.validator.ResponseValidatorTypedException"
    }
  ]
}

ee:variables.ee:set-variable:
%dw 2.0
output application/xml
ns ns0 http://tempuri.org/
ns ns01 http://www.etb.com.co/orquestador
---
{
	ns0#ProcesarOrden: {
		ns0#solicitudOrden: {
			ns01#Encabezado: {
				ns01#Propiedades: {
					ns01#Propiedad: {
						ns01#Nombre: "",
						ns01#Valor: ""
					}
				},
				ns01#Sistema: {
					ns01#IdCorrelacion: payload.Numero_Orden,
					ns01#Nombre: "MULESOFT",
					ns01#Servidor: "MULESOFT"
				}
			},
			ns01#DatosSolicitud: {
				ns01#EstadoOrden: payload.Estado_Orden_Comercial.Codigo,
				ns01#NumeroOrden: payload.Numero_Orden,
				ns01#Tramite: vars.transactType,
				ns01#UsuarioEvento: ""
			}
		}
	}
}

ee:message.ee:set-payload:
%dw 2.0
output application/json
var status = payload.ProcesarOrdenResponse.Resultado.Encabezado.Servicio.Estado
---
if(status == "OK") 
{
  "status": payload.ProcesarOrdenResponse.Resultado.Estado.Codigo default payload.ProcesarOrdenResponse.Resultado.Encabezado.Servicio.Codigo,
  "orderNumber":vars.orderExample.consecutive,
  "description": payload.ProcesarOrdenResponse.Resultado.Estado.Descripcion default payload.ProcesarOrdenResponse.Resultado.Encabezado.Servicio.DetalleEstado
} 
else 
{
  "status": 500,
  "code": "INTERNAL_SERVER_ERROR",
  "message": {
    "message": payload.ProcesarOrdenResponse.Resultado.Estado.Descripcion default payload.ProcesarOrdenResponse.Resultado.Encabezado.Servicio.DetalleEstado
  },
  "messageServer": "",
  "cause": [
    {
      "origin": app.name,
      "message": "org.mule.extension.http.api.request.validator.ResponseValidatorTypedException"
    }
  ]
}

ee:variables.ee:set-variable:
%dw 2.0
output application/json
---
{
	Id: vars.idAsset,
	estado: "Inactivo",
	fecha: (now() >> "America/Bogota") as String {format:"YYYY-MM-dd"}
}
